#include "opc_runtime.h"
#include "opc_runtime_arm.h"
#include <string.h>


/*********************************************************************************
* function: request DDR memory
* param: mem_addr    - I               start Address
*         offset      - I               valid address offset value
*         mem_size    - I               current application size
* return: memory pointer returned on success, NULL returned on failure
* note: 
***********************************************************************************/
void* OPC_RUNTIME_malloc(void* mem_addr, unsigned int offset, unsigned int mem_size)
{
    if(NULL != mem_addr)
    {
        offset = OPC_SIZE_ALIGN_128((SIZE_T)offset);
        memset(mem_addr + offset, 0, mem_size);
        return (void*)((char*)mem_addr + offset);
    }
    else
    {
        return NULL;
    }
}


/*********************************************************************************
* function: free DDR memory
* param: ptr     - I                memory pointer
* return: 0 returned on success, -1 returned on failure
* note: Only the reverse order of opening is supported, otherwise the space will be released by mistake.
* Empty memory generated by pre ptr alignment is not released
***********************************************************************************/
int OPC_RUNTIME_free(void* ptr)  //
{
    return 0;
}
